  const LANGUAGES=[['English (India)','en-IN'],['English (International)','en-GB'],['Assamese','as-IN'],['Bengali','bn-IN'],['Bodo','brx-IN'],['Dogri','doi-IN'],['Gujarati','gu-IN'],['Hindi','hi-IN'],['Kannada','kn-IN'],['Kashmiri','ks-IN'],['Konkani','kok-IN'],['Maithili','mai-IN'],['Malayalam','ml-IN'],['Manipuri (Meitei)','mni-IN'],['Marathi','mr-IN'],['Nepali','ne-IN'],['Odia','or-IN'],['Punjabi','pa-IN'],['Sanskrit','sa-IN'],['Santali','sat-IN'],['Sindhi','sd-IN'],['Tamil','ta-IN'],['Telugu','te-IN'],['Urdu','ur-IN']];
  function languageTag(value='en-IN'){const s=String(value||'en-IN').toLowerCase();const found=LANGUAGES.find(([name,tag])=>tag.toLowerCase()===s||name.toLowerCase()===s);if(found)return found[1];const aliases=[['gujarati','gu-IN'],['hindi','hi-IN'],['marathi','mr-IN'],['bengali','bn-IN'],['tamil','ta-IN'],['telugu','te-IN'],['kannada','kn-IN'],['malayalam','ml-IN'],['punjabi','pa-IN'],['odia','or-IN'],['oriya','or-IN'],['assamese','as-IN'],['urdu','ur-IN'],['nepali','ne-IN'],['sanskrit','sa-IN'],['english · international','en-GB']];return aliases.find(([name])=>s.includes(name))?.[1]||(/^([a-z]{2,3}-[a-z]{2})$/i.test(value)?value:'en-IN')}
