  function notify(msg){const t=$("#toast");if(!t)return;t.textContent=msg;t.classList.add("show");clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove("show"),3000)}
  function setView(view,label){if(!document.getElementById(view))view='home';const targetView=document.getElementById(view);$$('.view').forEach(x=>{x.classList.toggle('active',x.id===view);x.classList.remove('is-entering')});$$('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$$('#mobile-nav [data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('.mobile-more-trigger')?.classList.toggle('active',!['home','meetings','schedule'].includes(view));$('#crumb').textContent=label||({home:'JARVIS Mode',tasks:'Tasks & reminders',contacts:'Contacts',business:'Quotes & payments'}[view]||view);if(location.hash!==`#${view}`)history.replaceState(null,'',`#${view}`);requestAnimationFrame(()=>{targetView.classList.remove('is-entering');void targetView.offsetWidth;targetView.classList.add('is-entering');setTimeout(()=>targetView.classList.remove('is-entering'),1000)});if(view==='tasks')renderTasks();if(view==='contacts')renderContacts();if(view==='business')renderBusiness();if(view==='schedule')renderSchedule();if(view==='memory')renderMemory();if(view==='meetings')renderMeetingHistory();window.scrollTo({top:0,behavior:'smooth'})}
  function navButton(view,label,icon){const b=document.createElement('button');b.dataset.view=view;b.innerHTML=`<svg viewBox="0 0 24 24"><path d="${icon}"/></svg>${label}`;$('.nav').append(b)}
