  function buildMobileNav(){if($('#mobile-nav'))return;const nav=document.createElement('nav');nav.id='mobile-nav';nav.className='mobile-nav';nav.setAttribute('aria-label','Main navigation');for(const [view,label] of [['home','Home'],['meetings','Meetings'],['schedule','Calendar']]){const source=$(`.nav [data-view="${view}"]`),b=document.createElement('button');b.dataset.view=view;b.innerHTML=`${source?.querySelector('svg')?.outerHTML||''}<span>${label}</span>`;b.addEventListener('click',()=>setView(view));nav.append(b)}const more=document.createElement('button');more.className='mobile-more-trigger';more.setAttribute('aria-expanded','false');more.innerHTML='<span class="mobile-more-icon">•••</span><span>More</span>';const menu=document.createElement('div');menu.className='mobile-more-menu';menu.hidden=true;more.addEventListener('click',()=>{menu.hidden=!menu.hidden;more.setAttribute('aria-expanded',String(!menu.hidden))});nav.append(more,menu);document.body.append(nav)}
  function refreshMobileMenu(){const menu=$('#mobile-nav .mobile-more-menu'),more=$('#mobile-nav .mobile-more-trigger');if(!menu)return;menu.replaceChildren();for(const source of $$('.nav [data-view]')){const b=document.createElement('button');b.dataset.view=source.dataset.view;b.textContent=source.textContent.trim().replace('NEW','').trim();b.addEventListener('click',()=>{setView(b.dataset.view,b.textContent);menu.hidden=true;more.setAttribute('aria-expanded','false')});menu.append(b)}}buildMobileNav();
  const scheduleHeading=$('#schedule .heading-row');if(scheduleHeading){const label=document.createElement('label');label.className='row-action';label.style.cursor='pointer';label.textContent='Import calendar (.ics)';label.innerHTML='Import calendar (.ics)<input id="calendar-import" type="file" accept=".ics,text/calendar" hidden>';scheduleHeading.append(label)}
  function section(id,title,sub,action){const s=document.createElement('section');s.className='view';s.id=id;s.innerHTML=`<div class="heading-row"><div><div class="eyebrow">PERSONAL WORKSPACE</div><h1>${title}</h1><p>${sub}</p></div>${action?`<button class="primary" data-action="${action}">+ Add new</button>`:''}</div><div class="data-page">${id==='business'?'<div class="card section-card"><div class="small-head"><b>Quotation drafts</b><button class="primary" data-action="add-quote">+ New quotation</button></div><div class="data-list" id="quote-list"></div></div><div class="card section-card"><div class="small-head"><b>Pending payments</b><button class="primary" data-action="add-payment">+ Add payment</button></div><div class="data-list" id="payment-list"></div></div>':`<div class="card section-card"><div class="data-toolbar"><input type="search" placeholder="Search ${title.toLowerCase()}…" data-search="${id}"><button class="primary" data-action="${action}">+ ${action==='add-task'?'Add task':action==='add-contact'?'Add contact':'Add reminder'}</button></div><div class="data-list" id="${id}-list"></div></div>`}</div>`;$('.content').append(s);return s}
  section('tasks','Tasks & reminders','Keep commitments and reminders together. Items are saved on this device.','add-task');section('contacts','Contacts','Your useful people and customer context, stored privately on this device.','add-contact');section('business','Quotes & payments','Track quotation drafts and payment follow-ups. Nothing is sent automatically.',null);
  const settings=$('#settings');const privacy=document.createElement('div');privacy.className='card section-card';privacy.innerHTML='<div class="small-head"><b>App data, AI & installation</b><span class="connection-badge offline" id="ai-status">Local assistant</span></div><p style="color:#91aaa0;font-size:11px;line-height:1.6">Your records stay in this browser unless you connect cloud sync. Add your own HTTPS AI server URL to enable open-ended answers and optional live web research. Keep API keys on that server; never paste them here.</p><div class="control"><label for="ai-server-url">AI server URL <span>optional</span></label><input id="ai-server-url" class="select-control" type="url" placeholder="https://your-private-ai-server.example" autocomplete="url"><small class="voice-availability">GitHub Pages cannot run the AI server. See README for the secure setup.</small></div><div class="toggle-row" style="margin-top:10px">Use web search for current questions <button class="toggle"></button></div><div class="data-toolbar"><button class="primary" data-action="export">Export my data</button><label class="row-action" style="cursor:pointer">Import backup<input type="file" id="import-file" accept="application/json" hidden></label><button class="row-action danger" data-action="wipe">Delete all local data</button><button class="install-cta" id="install-app">Install app</button></div><div style="font-size:10px;color:#8ca99d">Voice activation is user initiated. Wake phrase listening is foreground-only where supported. Meeting recording is never started by voice command.</div>';
  settings.append(privacy);
