  const admin=section('admin','Workspace & admin','Manage the workspace name and this device’s account settings.',null);admin.querySelector('.data-page').innerHTML='<div class="card section-card"><h2>Workspace profile</h2><p>These settings sync with this signed-in account when cloud sync is configured.</p><form id="workspace-form" class="controls"><div class="control"><label for="workspace-name-input">Workspace name</label><input id="workspace-name-input" class="select-control" maxlength="60" required></div><div class="control"><label for="workspace-owner-input">Your display name</label><input id="workspace-owner-input" class="select-control" maxlength="60" placeholder="Workspace owner"></div><button class="primary" type="submit">Save workspace settings</button></form></div><div class="card section-card" style="margin-top:14px"><h2>Access and administration</h2><p>Role: Workspace owner on this device. Team invitations, shared member roles, and centralized access controls require a connected multi-user workspace backend; they are not available in this personal PWA yet.</p><div class="setting-line"><span>Storage mode</span><b id="admin-storage-status">Checking…</b></div></div>';
  navButton('admin','Workspace admin','M4 3h16v18H4zM8 8h8m-8 4h8m-8 4h4');refreshMobileMenu();
  const sidebar=$('aside'),sidebarToggle=document.createElement('button');sidebarToggle.type='button';sidebarToggle.className='sidebar-toggle';sidebarToggle.setAttribute('aria-label','Collapse sidebar');sidebarToggle.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14.5 5-7 7 7 7"/></svg>';$('.brand')?.append(sidebarToggle);const setSidebarCollapsed=collapsed=>{document.querySelector('.app')?.classList.toggle('sidebar-collapsed',collapsed);sidebarToggle.setAttribute('aria-expanded',String(!collapsed));sidebarToggle.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');sidebarToggle.title=sidebarToggle.getAttribute('aria-label')};setSidebarCollapsed(localStorage.getItem('meetingmind.sidebar.collapsed')==='true');sidebarToggle.addEventListener('click',()=>{const collapsed=!document.querySelector('.app')?.classList.contains('sidebar-collapsed');setSidebarCollapsed(collapsed);localStorage.setItem('meetingmind.sidebar.collapsed',String(collapsed))});
  const adminAiCard=document.createElement('div');adminAiCard.className='card section-card admin-ai-card';adminAiCard.innerHTML=`<div class="small-head"><h2>AI assistant connection</h2><span id="admin-ai-status" class="connection-badge offline">Not connected</span></div><p>Deploy this repository to Render as a Blueprint. The provider key stays private on Render; the app uses a separate access token so the public service cannot be called anonymously.</p><ol class="admin-setup-steps"><li>Open Render and choose <b>New → Blueprint</b>. Connect <b>Codex26-dev/MeetingMind</b> on <b>main</b> and deploy the root <code>render.yaml</code>.</li><li>In the service’s <b>Environment</b>, add <code>OPENAI_API_KEY</code> (your OpenAI key) and <code>APP_ACCESS_TOKEN</code> (a long random password you create). Keep both private and save/deploy.</li><li>Paste the service HTTPS URL and the same <code>APP_ACCESS_TOKEN</code> below, then choose <b>Save and test</b>.</li></ol><p class="admin-secret-note">Never enter <code>OPENAI_API_KEY</code> here. Only the separate app access token is saved in this browser’s private app settings, outside exports and backups. Anyone with this browser profile can use the token; rotate it in Render if needed.</p><p><a href="https://dashboard.render.com/blueprints" target="_blank" rel="noopener noreferrer">Open Render Blueprint setup ↗</a> · <a href="https://render.com/docs/configure-environment-variables" target="_blank" rel="noopener noreferrer">Where to add the secrets</a></p><div class="control"><label for="admin-ai-url">Render AI service URL</label><input id="admin-ai-url" class="select-control" type="url" placeholder="https://meetingmind-ai-5iqb.onrender.com" autocomplete="url"></div><div class="control"><label for="admin-ai-token">App access token <span>not your OpenAI key</span></label><input id="admin-ai-token" class="select-control" type="password" autocomplete="off" placeholder="Same value as APP_ACCESS_TOKEN on Render"></div><button id="admin-ai-save" class="primary" type="button">Save and test connection</button>`;const adminData=admin.querySelector('.data-page');adminData.insertBefore(adminAiCard,adminData.lastElementChild);const adminAiUrl=$('#admin-ai-url'),adminAiToken=$('#admin-ai-token');adminAiUrl.value=db.settings.aiServerUrl||'';adminAiToken.value=aiAccessToken;$('#admin-ai-save').addEventListener('click',()=>{const value=adminAiUrl.value.trim().replace(/\/$/,''),token=adminAiToken.value.trim();if(value&&!/^https:\/\//i.test(value)){notify('Use the HTTPS URL shown for your Render service.');return}db.settings.aiServerUrl=value;aiAccessToken=token;if(token)localStorage.setItem(AI_TOKEN_KEY,token);else localStorage.removeItem(AI_TOKEN_KEY);save();if(aiUrlInput)aiUrlInput.value=value;refreshAiConnection().then(()=>notify(aiAvailable?'AI server connected and ready':'Saved. Check the connection status above.'))});
  const supabaseCard=document.createElement('div');supabaseCard.className='card section-card supabase-setup-card';supabaseCard.innerHTML=`<div class="small-head"><h2>Email sign-in & cross-device sync</h2><span id="supabase-admin-status" class="connection-badge offline">Not connected</span></div><p>MeetingMind already supports Supabase email-code sign-in and per-user cloud sync. Connect your own Supabase project here; the browser uses only its publishable/anon key and the included table policy.</p><ol class="admin-setup-steps"><li>Create or open your project in Supabase, then copy its Project URL and publishable key from the project API settings.</li><li>Run the included <code>supabase/schema.sql</code> once in SQL Editor. This creates the account-owned data row with row-level security.</li><li>In Auth → URL Configuration, set Site URL to <code>https://codex26-dev.github.io/MeetingMind/</code> and add it to Redirect URLs. In the email template, use <code>{{ .Token }}</code> so the message contains a one-time code rather than only a link.</li><li>Save the project connection below, then sign in with email. Use the same project URL and publishable key on each device.</li></ol><p><a href="https://supabase.com/dashboard/projects" target="_blank" rel="noopener noreferrer">Open Supabase projects ↗</a> · <a href="https://github.com/Codex26-dev/MeetingMind/blob/main/supabase/schema.sql" target="_blank" rel="noopener noreferrer">Open the SQL policy</a> · <a href="https://supabase.com/docs/guides/auth/auth-email-templates" target="_blank" rel="noopener noreferrer">Configure email codes</a></p><div class="control"><label for="admin-supabase-url">Supabase project URL</label><input id="admin-supabase-url" class="select-control" type="url" placeholder="https://your-project.supabase.co" autocomplete="url"></div><div class="control"><label for="admin-supabase-key">Publishable / anon key <span>never service_role</span></label><input id="admin-supabase-key" class="select-control" type="password" autocomplete="off" placeholder="sb_publishable_… or legacy anon key"></div><button id="admin-supabase-save" class="primary" type="button">Save and test Supabase</button><p class="admin-secret-note">I can’t create the project without an authenticated Supabase account. I’ll finish the live connection after the project URL and publishable key are available. The service-role key is never needed in MeetingMind.</p>`;adminData.insertBefore(supabaseCard,adminData.lastElementChild);const supaUrl=$('#admin-supabase-url'),supaKey=$('#admin-supabase-key'),SUPABASE_CONFIG_KEY='meetingmind.supabase.config.v1';let supaConfig={};try{supaConfig=JSON.parse(localStorage.getItem(SUPABASE_CONFIG_KEY)||'{}')}catch{}supaUrl.value=supaConfig.url||'';supaKey.value=supaConfig.anonKey||'';const supaStatus=$('#supabase-admin-status');if(supaConfig.url&&supaConfig.anonKey){supaStatus.textContent='Settings saved · test needed';supaStatus.classList.add('offline')}$('#admin-supabase-save').addEventListener('click',async()=>{const url=supaUrl.value.trim().replace(/\/$/,''),anonKey=supaKey.value.trim();if(!/^https:\/\/[\w.-]+\.supabase\.co$/.test(url)||!anonKey){notify('Enter your Supabase Project URL and publishable/anon key.');return}supaStatus.textContent='Testing connection…';supaStatus.classList.add('offline');try{const r=await fetch(`${url}/auth/v1/settings`,{headers:{apikey:anonKey}});if(!r.ok)throw Error(`Supabase returned ${r.status}. Check the URL and publishable key.`);localStorage.setItem(SUPABASE_CONFIG_KEY,JSON.stringify({url,anonKey}));supaStatus.textContent='Supabase reachable · email sign-in ready';supaStatus.classList.remove('offline');notify('Supabase settings saved on this device. Sign-in and cloud sync are ready to try.')}catch(e){supaStatus.textContent='Connection failed';notify(e.message||'Could not reach Supabase. Check the project URL, key, and project status.')}});
  function renderWorkspace(){const name=db.settings.workspaceName||'My Workspace',owner=db.settings.ownerName||'';const title=$('.workspace strong');if(title)title.textContent=name;const avatar=$('.workspace .avatar');if(avatar)avatar.textContent=name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();const input=$('#workspace-name-input'),ownerInput=$('#workspace-owner-input');if(input)input.value=name;if(ownerInput)ownerInput.value=owner;const status=$('#admin-storage-status');if(status)status.textContent=window.MMAuth?.mode==='email'?'Signed-in account':'This device'}
  renderWorkspace();window.addEventListener('meetingmind:authchange',renderWorkspace);$('#workspace-form')?.addEventListener('submit',e=>{e.preventDefault();db.settings.workspaceName=$('#workspace-name-input').value.trim()||'My Workspace';db.settings.ownerName=$('#workspace-owner-input').value.trim();save();renderWorkspace();notify('Workspace settings saved')});
  function aiEndpoint(path){const base=(db.settings.aiServerUrl||'').trim().replace(/\/$/,'');return base?`${base}/api/${path}`:`./api/${path}`}
  async function refreshAiConnection(){const badges=[$('#ai-status'),$('#admin-ai-status')].filter(Boolean);if(!badges.length)return;badges.forEach(b=>{b.textContent='Checking AI server…';b.classList.add('offline')});try{const r=await fetch(aiEndpoint('health'));if(!r.ok)throw Error();const x=await r.json();aiAvailable=!!x.aiConfigured&&!!aiAccessToken&&!!x.accessProtected;const label=aiAvailable?`AI ready · ${x.provider}${x.webSearchAvailable?' · web search':''}`:!x.ok?'AI server is not configured':!aiAccessToken?'Add the app access token below':'Add OPENAI_API_KEY and APP_ACCESS_TOKEN in Render';badges.forEach(b=>{b.textContent=label;b.classList.toggle('offline',!aiAvailable)})}catch{aiAvailable=false;badges.forEach(b=>{b.textContent=db.settings.aiServerUrl?'Could not reach AI server':'No AI server connected';b.classList.add('offline')})}}
  function renderTasks(filter=''){const list=$('#tasks-list');if(!list)return;const q=filter.toLowerCase();const tasks=db.tasks.filter(x=>`${x.title} ${x.notes||''}`.toLowerCase().includes(q)).sort((a,b)=>a.due.localeCompare(b.due));list.innerHTML=tasks.length?tasks.map(t=>`<div class="data-row" data-id="${esc(t.id)}"><div class="data-icon">${t.done?'✓':'◷'}</div><div><strong style="${t.done?'text-decoration:line-through;opacity:.65':''}">${esc(t.title)}</strong><small>${esc(t.notes||'Reminder')} · ${t.done?'Completed':fmtDate(t.due)}${!t.done&&t.due<today()?' · OVERDUE':''}</small></div><div class="row-actions"><button class="row-action" data-action="toggle-task">${t.done?'Reopen':'Complete'}</button><button class="row-action danger" data-action="delete-task">Delete</button></div></div>`).join(''):'<div class="empty-state"><b>No tasks here yet</b>Add a reminder or ask MeetingMind to remind you about something.</div>'}
