  function addBubble(text,role='assistant',action,store=true,sources=[]){if(window.MMReactChatReady){if(store){db.history.push({role,text,at:new Date().toISOString(),...(sources.length?{sources}:{})});if(db.history.length>100)db.history=db.history.slice(-100);save()}notifyHistory();return null}const msg=document.createElement('div');msg.className=`message ${role==='user'?'user':''}`;if(role==='assistant'){const orb=document.createElement('div');orb.className='mini-orb';msg.append(orb)}const b=document.createElement('div');b.className='bubble';b.append(document.createTextNode(text));const meta=document.createElement('span');meta.className='meta';meta.textContent=role==='user'?'You · just now':'MeetingMind · just now';b.append(meta);if(sources.length){const box=document.createElement('div');box.className='answer-sources';const heading=document.createElement('small');heading.textContent='Sources';box.append(heading);sources.forEach(source=>{try{const u=new URL(source.url);if(!['https:','http:'].includes(u.protocol))return;const a=document.createElement('a');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent=source.title||u.hostname;box.append(a)}catch{}});if(box.querySelector('a'))b.append(box)}if(action){const a=document.createElement('button');a.className='row-action';a.textContent=action.label;a.style.marginTop='8px';a.dataset.action=action.action;a.dataset.id=action.id||'';b.append(document.createElement('br'),a)}msg.append(b);chat.append(msg);chat.scrollTop=chat.scrollHeight;if(store){db.history.push({role,text,at:new Date().toISOString(),...(sources.length?{sources}:{})});if(db.history.length>100)db.history=db.history.slice(-100);save()}return msg}
