  function scheduleReminder(task){if(!('Notification'in window)||Notification.permission!=='granted')return;const delay=new Date(`${task.due}T09:00`).getTime()-Date.now();if(delay>0&&delay<2147483647){setTimeout(()=>showDeviceNotification('MeetingMind reminder',task.title,task.id),delay)}}
  let proactiveTimers=[];function scheduleProactive(){proactiveTimers.forEach(clearTimeout);proactiveTimers=[];if(!('Notification'in window)||Notification.permission!=='granted')return;if(db.settings.morningBriefing){const now=new Date(),when=new Date();when.setHours(8,0,0,0);if(when<=now)when.setDate(when.getDate()+1);const delay=when.getTime()-now.getTime();if(delay<2147483647)proactiveTimers.push(setTimeout(()=>showDeviceNotification('Your MeetingMind morning briefing',`${db.meetings.filter(x=>x.date===today()).length} meetings today · ${db.tasks.filter(x=>!x.done).length} open follow-ups`,'morning-briefing'),delay))}if(db.settings.meetingAlerts){db.meetings.filter(m=>m.date>=today()).forEach(m=>{const when=new Date(`${m.date}T${m.time||'09:00'}`).getTime()-5*60*1000;if(when<=Date.now()||when-Date.now()>2147483647)return;const hour=new Date(when).getHours();if(db.settings.quietHours&&(hour>=22||hour<7))return;proactiveTimers.push(setTimeout(()=>showDeviceNotification('Meeting in 5 minutes',m.title,`meeting-${m.id}`),when-Date.now()))})}}
  function selectRelevantContext(query){const words=[...new Set(query.toLowerCase().match(/[a-z0-9]{3,}|[\u0900-\u097f\u0a80-\u0aff]{2,}/g)||[])];const rank=items=>items.map(x=>({x,score:words.reduce((n,w)=>n+(JSON.stringify(x).toLowerCase().includes(w)?1:0),0)})).sort((a,b)=>b.score-a.score).slice(0,5).map(z=>z.x);return {meetings:rank(db.meetings),tasks:rank(db.tasks.filter(t=>!t.done)),contacts:rank(db.contacts),quotes:rank(db.quotes),payments:rank(db.payments.filter(p=>p.status==='Pending')),memories:rank(db.memories)}}
  function readOnlyRecordLookup(query){const q=String(query||'').toLowerCase(),words=[...new Set(q.match(/[a-z0-9]{3,}|[\u0900-\u097f\u0a80-\u0aff]{2,}/g)||[])],score=x=>words.reduce((n,w)=>n+(JSON.stringify(x).toLowerCase().includes(w)?1:0),0),out={};if(/meeting|calendar|schedule|agenda|today|tomorrow|next|attendee|discuss|promise|commitment/.test(q)){let meetings=[...db.meetings].filter(m=>!m.completedAt).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));if(/today/.test(q))meetings=meetings.filter(m=>m.date===today());else if(/tomorrow/.test(q))meetings=meetings.filter(m=>m.date===shiftDay(1));else meetings=meetings.filter(m=>m.date>=today());out.meetings=meetings.slice(0,5).map(m=>({date:m.date,time:m.time,title:m.title,customer:m.customer,attendees:m.attendees,notes:m.notes,transcript:String(m.transcript||'').slice(0,900)}))}if(/task|remind|reminder|todo|due|overdue|pending work/.test(q)){out.tasks=db.tasks.filter(t=>!t.done).sort((a,b)=>(a.due||'').localeCompare(b.due||'')).slice(0,6).map(t=>({title:t.title,due:t.due,notes:t.notes}))}if(/contact|customer|supplier|phone|email|who is|number for/.test(q)){const matches=db.contacts.map(c=>({c,s:score(c)})).filter(x=>x.s>0||words.length===0).sort((a,b)=>b.s-a.s).slice(0,4);out.contacts=matches.map(({c})=>({name:c.name,company:c.company,phone:/phone|number/.test(q)?c.phone:undefined,email:/email/.test(q)?c.email:undefined,notes:c.notes}))}if(/quote|quotation|payment|invoice/.test(q)){out.quotations=db.quotes.map(x=>({title:x.title,customer:x.customer,status:x.status,amount:x.amount,followUpDue:x.followUpDue,outcome:x.outcome,notes:x.notes})).filter(x=>score(x)>0||/all|list|pending/.test(q)).slice(0,5);out.payments=db.payments.map(x=>({customer:x.customer,status:x.status,amount:x.amount,due:x.due,notes:x.notes})).filter(x=>score(x)>0||/all|list|pending/.test(q)).slice(0,5)}if(/memory|remember|note|discuss|promise|commitment/.test(q)){out.memories=db.memories.map(m=>({title:m.title,body:m.body})).filter(x=>score(x)>0).slice(0,4)}const content=JSON.stringify(out);return Object.keys(out).length?content.slice(0,8000):'No matching saved MeetingMind records were found. Ask the user to add the details if they want me to remember them.'}
  function dueDateFromText(text){const x=text.toLowerCase(),days=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];if(/\btomorrow\b/.test(x))return shiftDay(1);if(/\bnext week\b/.test(x))return shiftDay(7);const inDays=/\bin\s+(\d+)\s+days?\b/.exec(x);if(inDays)return shiftDay(Math.min(365,Number(inDays[1])));const weekday=/\b(?:next\s+)?(sunday|monday|tuesday|wednesday|thursday|friday|saturday)\b/.exec(x);if(weekday){const delta=(days.indexOf(weekday[1])-new Date().getDay()+7)%7||7;return shiftDay(delta)}return /\btoday\b/.test(x)?today():today()}
